def factorial(x):
    result = 1
    for k in range(2, x + 1):
        result *= k                              # recomputed from scratch on every single call
    return result

def right_pascals_triangle(n):
    for i in range(n):                          # row i has i + 1 entries
        row = []
        for j in range(i + 1):
            value = factorial(i) // (factorial(j) * factorial(i - j))  # the binomial coefficient formula
            row.append(str(value))
        print(" ".join(row))                      # left aligned, space separated


if __name__ == "__main__":
    right_pascals_triangle(5)

