import java.util.*;

public class Main {
    long factorial(int x) {
        long result = 1;
        for (int k = 2; k <= x; k++) {
            result *= k;                                // recomputed from scratch on every single call
        }
        return result;
    }

    void rightPascalsTriangle(int n) {
        for (int i = 0; i < n; i++) {                  // row i has i + 1 entries
            StringBuilder row = new StringBuilder();
            for (int j = 0; j <= i; j++) {
                long value = factorial(i) / (factorial(j) * factorial(i - j));  // the binomial coefficient formula
                if (j > 0) {
                    row.append(" ");
                }
                row.append(value);
            }
            System.out.println(row);                     // left aligned, space separated
        }
    }

    public static void main(String[] args) {
        Main solution = new Main();
        solution.rightPascalsTriangle(5);
    }
}

